import type { ConcreteSongLanguage, ServiceLanguage } from "./model";

export type RowLanguage = "" | ConcreteSongLanguage;

export type RowLanguageState = {
  songLanguage: RowLanguage;
  songNumber?: string;
  note?: string;
  languageTouched?: boolean;
};

export function formatDateInputValue(date: Date): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

export function getNearestSunday(fromDate: Date): Date {
  const nearestSunday = new Date(fromDate);
  nearestSunday.setHours(0, 0, 0, 0);
  const daysUntilSunday = (7 - nearestSunday.getDay()) % 7;
  nearestSunday.setDate(nearestSunday.getDate() + daysUntilSunday);
  return nearestSunday;
}

export function isSecondSunday(date: Date): boolean {
  return date.getDay() === 0 && date.getDate() >= 8 && date.getDate() <= 14;
}

export function getDefaultServiceLanguage(serviceDate: Date): ServiceLanguage {
  return isSecondSunday(serviceDate) ? "polish" : "czech";
}

export function getDefaultRowLanguage(serviceLanguage: ServiceLanguage): RowLanguage {
  if (serviceLanguage === "mixed") {
    return "";
  }
  return serviceLanguage;
}

export function isUntouchedEmptyRow(row: RowLanguageState): boolean {
  return !row.languageTouched && !row.songNumber?.trim() && !row.note?.trim();
}

export function propagateServiceLanguageToRows<TRow extends RowLanguageState>(
  rows: TRow[],
  serviceLanguage: ServiceLanguage,
): TRow[] {
  const defaultRowLanguage = getDefaultRowLanguage(serviceLanguage);
  return rows.map((row) => (isUntouchedEmptyRow(row) ? { ...row, songLanguage: defaultRowLanguage } : row));
}

export function getLanguageDeviationRowNumbers(rows: RowLanguageState[], serviceLanguage: ServiceLanguage): number[] {
  if (serviceLanguage === "mixed") {
    return [];
  }

  return rows.flatMap((row, index) => (row.songLanguage !== serviceLanguage ? [index + 1] : []));
}

export function shouldBlockSaveForLanguageDeviation(
  rows: RowLanguageState[],
  serviceLanguage: ServiceLanguage,
  confirmed: boolean,
): boolean {
  return getLanguageDeviationRowNumbers(rows, serviceLanguage).length > 0 && !confirmed;
}

export function normalizeServiceTime(value: string): string {
  const trimmed = value.trim();
  const match = /^(\d{2}):(\d{2})(?::\d{2})?$/.exec(trimmed);
  if (!match) {
    return trimmed;
  }

  return `${match[1]}:${match[2]}`;
}

export function isValidServiceTime(value: string): boolean {
  const normalized = normalizeServiceTime(value);
  const match = /^(\d{2}):(\d{2})$/.exec(normalized);
  if (!match) {
    return false;
  }

  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  return hours >= 0 && hours <= 23 && minutes >= 0 && minutes <= 59;
}

import type { ConcreteSongLanguage, ServiceLanguage, ServiceTopicReference } from "./model";

export function serviceTopicLanguageFromId(id: string): ConcreteSongLanguage | undefined {
  if (id.startsWith("czech:")) return "czech";
  if (id.startsWith("polish:")) return "polish";
  return undefined;
}

export function serviceTopicMatchesLanguage(topic: Pick<ServiceTopicReference, "id">, serviceLanguage: ServiceLanguage): boolean {
  const topicLanguage = serviceTopicLanguageFromId(topic.id);
  return Boolean(topicLanguage && (serviceLanguage === "mixed" || topicLanguage === serviceLanguage));
}

import { normalizeServiceTime } from "./service-time";
import type { CompletedServiceRecord, CompletedServiceRecordId, PlanningPlanId } from "../application/planning-lifecycle/ports";
import type { PlanningRole } from "./model";

export type PersistedRecordReference =
  | { kind: "active"; id: PlanningPlanId }
  | { kind: "completed"; id: CompletedServiceRecordId };

export type DraftPeopleDefaults = Pick<CompletedServiceRecord["serviceContext"], "priest" | "organist">;

export function getNewestCompletedRecord(records: CompletedServiceRecord[]): CompletedServiceRecord | undefined {
  return [...records].sort((a, b) => {
    const serviceDate = b.serviceContext.serviceDate.localeCompare(a.serviceContext.serviceDate);
    if (serviceDate !== 0) return serviceDate;
    const serviceTime = normalizeServiceTime(b.serviceContext.serviceTime).localeCompare(normalizeServiceTime(a.serviceContext.serviceTime));
    if (serviceTime !== 0) return serviceTime;
    const completedAt = new Date(b.completedAt).getTime() - new Date(a.completedAt).getTime();
    if (completedAt !== 0) return completedAt;
    return compareRecordIds(b.id, a.id);
  })[0];
}

export function getDraftPeopleDefaults(records: CompletedServiceRecord[]): DraftPeopleDefaults {
  const newest = getNewestCompletedRecord(records);
  return {
    priest: newest?.serviceContext.priest ?? { displayName: "Anonymous" },
    organist: newest?.serviceContext.organist ?? { displayName: "Anonymous" },
  };
}

export function canMutatePlanningEditor(input: {
  isFinalSetOpen: boolean;
  isCompletedRecordOpen: boolean;
  selectedRole: PlanningRole;
}): boolean {
  if (input.isFinalSetOpen) return false;
  if (!input.isCompletedRecordOpen) return true;
  return input.selectedRole === "admin";
}

export function clearLastSavedRecordOnOpen(): null {
  return null;
}

export function recordListClassName(isOpen: boolean, isLastSaved: boolean): string | undefined {
  if (isOpen) return "selected-record";
  if (isLastSaved) return "last-saved-record";
  return undefined;
}

function compareRecordIds(left: string, right: string): number {
  const leftNumber = Number.parseInt(left.replace(/\D/g, ""), 10);
  const rightNumber = Number.parseInt(right.replace(/\D/g, ""), 10);
  if (Number.isFinite(leftNumber) && Number.isFinite(rightNumber) && leftNumber !== rightNumber) {
    return leftNumber - rightNumber;
  }
  return left.localeCompare(right);
}

import type {
  ConcreteSongLanguage,
  PlanningPlan,
  PlanningPlanStatus,
  PlanningRow,
  ServiceLanguage,
  SongReference,
} from "./model";

export type PlanningValidationIssue = {
  path: string;
  message: string;
};

export type PlanningValidationResult = {
  valid: boolean;
  issues: PlanningValidationIssue[];
};

const concreteSongLanguages: readonly ConcreteSongLanguage[] = ["czech", "polish"];

function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

export function isConcreteSongLanguage(value: unknown): value is ConcreteSongLanguage {
  return concreteSongLanguages.includes(value as ConcreteSongLanguage);
}

export function validateSongReference(song: Partial<SongReference> | undefined): PlanningValidationIssue[] {
  const issues: PlanningValidationIssue[] = [];

  if (!song) {
    issues.push({ path: "song", message: "Song reference is required." });
    return issues;
  }

  if (!isNonEmptyString(song.number)) {
    issues.push({ path: "song.number", message: "Song number must be a non-empty string." });
  }

  if (song.songId !== undefined && !isNonEmptyString(song.songId)) {
    issues.push({ path: "song.songId", message: "Song catalog ID must be a non-empty string when present." });
  }

  if (song.title !== undefined && !isNonEmptyString(song.title)) {
    issues.push({ path: "song.title", message: "Song title snapshot must be a non-empty string when present." });
  }

  if (!isConcreteSongLanguage(song.language)) {
    issues.push({
      path: "song.language",
      message: "Song language must be either czech or polish.",
    });
  }

  return issues;
}

export function validatePlanningRow(row: PlanningRow): PlanningValidationResult {
  const issues: PlanningValidationIssue[] = [];
  const hasSongValue = row.song !== undefined;
  const hasTextualNote = isNonEmptyString(row.note);

  if (hasSongValue) {
    issues.push(...validateSongReference(row.song));
  }

  if (!hasSongValue && !hasTextualNote) {
    issues.push({
      path: "row",
      message: "Row must include either a complete song reference or a non-empty textual note.",
    });
  }

  return {
    valid: issues.length === 0,
    issues,
  };
}

const serviceLanguages: readonly ServiceLanguage[] = ["czech", "polish", "mixed"];
const planningPlanStatuses: readonly PlanningPlanStatus[] = ["working", "final"];

export function validatePlanningSet(plan: PlanningPlan): PlanningValidationResult {
  const issues: PlanningValidationIssue[] = [];

  if (!planningPlanStatuses.includes(plan.status)) {
    issues.push({ path: "status", message: "Planning set status must be either working or final." });
  }

  if (!serviceLanguages.includes(plan.language)) {
    issues.push({ path: "language", message: "Planning set language must be czech, polish, or mixed." });
  }

  if (!Array.isArray(plan.rows)) {
    issues.push({ path: "rows", message: "Planning set rows must be an array." });
  } else {
    if (plan.rows.length > 10) {
      issues.push({ path: "rows", message: "Planning set cannot contain more than 10 rows." });
    }

    plan.rows.forEach((row, index) => {
      const rowValidation = validatePlanningRow(row);
      rowValidation.issues.forEach((issue) => {
        issues.push({
          path: `rows.${index}.${issue.path}`,
          message: issue.message,
        });
      });
    });
  }

  return {
    valid: issues.length === 0,
    issues,
  };
}

/** Canonical Plan-named validator; historical Set export remains during call-site migration. */
export const validatePlanningPlan = validatePlanningSet;

import type { PersistedPlanningPlan } from "../application/planning-lifecycle/ports";
import { whatsAppPhoneDigits } from "../application/whatsapp-phone";

export function formatFinalPlanWhatsAppMessage(plan: PersistedPlanningPlan): string {
  const context = plan.serviceContext;
  const lines = [
    "Final plan",
    `Date: ${context.serviceDate}`,
    `Time: ${context.serviceTime}`,
    `Language: ${context.language}`,
    `Priest: ${context.priest.displayName}`,
    `Organist: ${context.organist.displayName}`,
  ];

  if (context.referenceAntiphon) {
    lines.push(`Antiphon: ${context.referenceAntiphon.displayNumber} ${context.referenceAntiphon.title}`.trim());
  }
  if (context.referenceTopic) lines.push(`Topic: ${context.referenceTopic.title}`);
  if (context.note?.trim()) lines.push(`Note: ${context.note.trim()}`);

  lines.push("", "Songs:");
  if (plan.rows.length === 0) {
    lines.push("—");
  } else {
    plan.rows.forEach((row, index) => {
      const song = row.song;
      const songText = song
        ? [song.number, song.title?.trim()].filter(Boolean).join(" ")
        : "—";
      const note = row.note?.trim();
      lines.push(`${index + 1}. ${songText}${note ? ` — ${note}` : ""}`);
    });
  }

  return lines.join("\n");
}

export function buildFinalPlanWhatsAppUrl(plan: PersistedPlanningPlan, phoneE164: string): string {
  return `https://wa.me/${whatsAppPhoneDigits(phoneE164)}?text=${encodeURIComponent(formatFinalPlanWhatsAppMessage(plan))}`;
}

import type { CompletedServiceRecord, PersistedPlanningPlan, PlanningPlanId, CompletedServiceRecordId } from "../application/planning-lifecycle/ports";
import type { PlanningRole } from "./model";
import { formatPlanningRowsSummary } from "./row-summary";

export type Workspace = "about" | "planning" | "plans" | "history" | "catalog" | "development" | "guide";
export type ActiveRecordGroups = { working: PersistedPlanningPlan[]; final: PersistedPlanningPlan[] };
export type PersistedRecordReference =
  | { kind: "active"; id: PlanningPlanId }
  | { kind: "completed"; id: CompletedServiceRecordId };

export function getAvailableWorkspaces(role: PlanningRole): Workspace[] {
  const base: Workspace[] = ["about", "planning", "plans", "history"];
  if (role === "admin") base.push("catalog");
  base.push("development", "guide");
  return base;
}

export function isWorkspaceAvailable(workspace: Workspace, role: PlanningRole): boolean {
  return getAvailableWorkspaces(role).includes(workspace);
}

export function getSafeWorkspace(workspace: Workspace, role: PlanningRole): Workspace {
  return isWorkspaceAvailable(workspace, role) ? workspace : "planning";
}

export function groupActivePlanningSets(plans: PersistedPlanningPlan[]): ActiveRecordGroups {
  return {
    working: plans.filter((plan) => plan.status === "working"),
    final: plans.filter((plan) => plan.status === "final"),
  };
}

/** Canonical Plan-named helper; historical Set export remains during call-site migration. */
export const groupActivePlanningPlans = groupActivePlanningSets;

export function formatPlanningSetSummary(plan: PersistedPlanningPlan): string {
  return [
    formatServiceContext(plan.serviceContext),
    formatPlanningRowsSummary(plan.rows),
    `changed by ${plan.lastChangedBy ?? "—"}`,
  ].join(" · ");
}

/** Canonical Plan-named helper; historical Set export remains during call-site migration. */
export const formatPlanningPlanSummary = formatPlanningSetSummary;

export function formatCompletedRecordSummary(record: CompletedServiceRecord): string {
  return [
    formatServiceContext(record.serviceContext),
    formatPlanningRowsSummary(record.set.rows),
    `changed by ${record.lastChangedBy ?? "—"}`,
  ].join(" · ");
}

export const workspaceLabels: Record<Workspace, string> = {
  about: "About",
  planning: "Planning",
  plans: "Plans",
  history: "History",
  catalog: "Catalog",
  development: "Development",
  guide: "Guide",
};

export function getWorkspaceLabel(workspace: Workspace): string { return workspaceLabels[workspace]; }
export function getWorkspaceAfterStartNewSet(): Workspace { return "planning"; }
/** Canonical Plan-named helper; historical Set export remains during call-site migration. */
export const getWorkspaceAfterStartNewPlan = getWorkspaceAfterStartNewSet;
export function getWorkspaceAfterSaveWorking(): Workspace { return "plans"; }
export function getWorkspaceAfterFinalize(): Workspace { return "plans"; }
export function getWorkspaceAfterComplete(): Workspace { return "history"; }
export function getWorkspaceAfterCompletedUpdate(): Workspace { return "history"; }
export function getWorkspaceAfterDelete(deleted: PersistedRecordReference | null, groups: ActiveRecordGroups, completed: CompletedServiceRecord[]): Workspace {
  if (deleted?.kind === "completed") return completed.length ? "history" : "planning";
  return groups.working.length || groups.final.length ? "plans" : "planning";
}
export function getWorkspaceAfterOpenRecord(): Workspace { return "planning"; }

function formatServiceContext(context: PersistedPlanningPlan["serviceContext"]): string {
  return `${context.serviceDate} ${context.serviceTime || "time missing"} · ${context.language} · ${context.priest.displayName || "—"} · ${context.organist.displayName || "—"}`;
}

